-- ─────────────────────────────────────────────────────────────────────────────
-- 0. Guard: ensure handle_updated_at() function exists
--    (created in a prior migration; included here as a safety net)
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. audience_segments — saved filter presets per studio
--    RLS: studio members read; owner/admin/manager write.
--    Audit trigger: yes (mutations are user-intent, worth logging).
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.audience_segments (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  studio_id   uuid        NOT NULL REFERENCES public.studios(id)     ON DELETE CASCADE,
  name        text        NOT NULL,
  -- Shape: { groups: [{ op: "AND"|"OR", conditions: [...] }], exclude: [...] }
  filter      jsonb       NOT NULL DEFAULT '{}'::jsonb,
  created_by  uuid        REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_audience_segments_studio_name UNIQUE (studio_id, name)
);

COMMENT ON TABLE  public.audience_segments                   IS 'Saved audience filter presets per studio.';
COMMENT ON COLUMN public.audience_segments.filter            IS 'JSONB shape: { groups: [{ op: AND|OR, conditions: [...] }], exclude: [...] }';
COMMENT ON COLUMN public.audience_segments.created_by        IS 'PII:L2 — user_id of creator';

ALTER TABLE public.audience_segments ENABLE ROW LEVEL SECURITY;

-- Members of the studio can read all segments
CREATE POLICY "audience_segments_select" ON public.audience_segments
  FOR SELECT USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members WHERE user_id = auth.uid()
    )
  );

-- Owner / admin / manager can insert
CREATE POLICY "audience_segments_insert" ON public.audience_segments
  FOR INSERT WITH CHECK (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid()
        AND role IN ('owner', 'admin', 'manager')
    )
  );

-- Owner / admin / manager can update
CREATE POLICY "audience_segments_update" ON public.audience_segments
  FOR UPDATE USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid()
        AND role IN ('owner', 'admin', 'manager')
    )
  )
  WITH CHECK (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid()
        AND role IN ('owner', 'admin', 'manager')
    )
  );

-- Owner / admin / manager can delete
CREATE POLICY "audience_segments_delete" ON public.audience_segments
  FOR DELETE USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid()
        AND role IN ('owner', 'admin', 'manager')
    )
  );

-- Indexes
CREATE INDEX IF NOT EXISTS idx_audience_segments_studio_id   ON public.audience_segments(studio_id);
CREATE INDEX IF NOT EXISTS idx_audience_segments_created_by  ON public.audience_segments(created_by);

-- updated_at trigger
DROP TRIGGER IF EXISTS set_audience_segments_updated_at ON public.audience_segments;
CREATE TRIGGER set_audience_segments_updated_at
  BEFORE UPDATE ON public.audience_segments
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

-- Audit trigger (reuses fn_inventory_audit pattern — generic direct INSERT into audit_log)
CREATE OR REPLACE FUNCTION fn_audience_segments_audit()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row     jsonb;
  v_old_row jsonb;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN COALESCE(NEW, OLD); END IF;
  IF    TG_OP = 'DELETE' THEN v_row := row_to_json(OLD)::jsonb; v_old_row := v_row;
  ELSIF TG_OP = 'INSERT' THEN v_row := row_to_json(NEW)::jsonb; v_old_row := NULL;
  ELSE                         v_row := row_to_json(NEW)::jsonb; v_old_row := row_to_json(OLD)::jsonb;
  END IF;
  INSERT INTO audit_log (action, actor_id, studio_id, target_type, target_id, details, created_at)
  VALUES (
    'audience_segments.' || lower(TG_OP),
    auth.uid(),
    (v_row->>'studio_id')::uuid,
    'audience_segments',
    v_row->>'id',
    CASE TG_OP
      WHEN 'INSERT' THEN jsonb_build_object('new', v_row)
      WHEN 'UPDATE' THEN jsonb_build_object('old', v_old_row, 'new', v_row)
      WHEN 'DELETE' THEN jsonb_build_object('old', v_row)
    END,
    now()
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS trg_audit_audience_segments ON public.audience_segments;
CREATE TRIGGER trg_audit_audience_segments
  AFTER INSERT OR UPDATE OR DELETE ON public.audience_segments
  FOR EACH ROW EXECUTE FUNCTION fn_audience_segments_audit();

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. marketing_sends — per-recipient send log
--    Inserts via RPC/worker (service role) only — no direct-insert RLS policy.
--    Members can read their studio's sends.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.marketing_sends (
  id                   uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id          uuid        NOT NULL REFERENCES public.marketing_campaigns(id) ON DELETE CASCADE,
  client_id            uuid        NOT NULL REFERENCES public.clients(id)             ON DELETE CASCADE,
  studio_id            uuid        NOT NULL REFERENCES public.studios(id)             ON DELETE CASCADE,
  channel              text        NOT NULL CHECK (channel IN ('email', 'sms')),
  recipient_email      text,
  recipient_phone      text,
  -- Lifecycle timestamps
  sent_at              timestamptz,
  opened_at            timestamptz,
  clicked_at           timestamptz,
  bounced_at           timestamptz,
  complained_at        timestamptz,
  unsubscribed_at      timestamptz,
  -- Attribution
  booking_id           uuid        REFERENCES public.bookings(id) ON DELETE SET NULL,
  -- Provider tracking
  provider_message_id  text        UNIQUE,      -- Resend message ID — used by webhook lookup
  error_message        text,
  created_at           timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE  public.marketing_sends                         IS 'Per-recipient delivery + engagement log for marketing campaigns.';
COMMENT ON COLUMN public.marketing_sends.provider_message_id    IS 'Resend message ID — unique constraint enables idempotent webhook updates.';
COMMENT ON COLUMN public.marketing_sends.recipient_email        IS 'PII:L3 — recipient email address, confidential';
COMMENT ON COLUMN public.marketing_sends.recipient_phone        IS 'PII:L3 — recipient phone number, confidential';

ALTER TABLE public.marketing_sends ENABLE ROW LEVEL SECURITY;

-- Studio members can read sends for their studio
CREATE POLICY "marketing_sends_select" ON public.marketing_sends
  FOR SELECT USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members WHERE user_id = auth.uid()
    )
  );

-- Inserts are service-role only (worker / Resend webhook handler)
-- No INSERT policy → app users cannot insert directly.

-- Indexes
CREATE INDEX IF NOT EXISTS idx_marketing_sends_campaign_id          ON public.marketing_sends(campaign_id);
CREATE INDEX IF NOT EXISTS idx_marketing_sends_client_id            ON public.marketing_sends(client_id);
CREATE INDEX IF NOT EXISTS idx_marketing_sends_studio_id            ON public.marketing_sends(studio_id);
CREATE INDEX IF NOT EXISTS idx_marketing_sends_campaign_opened      ON public.marketing_sends(campaign_id, opened_at);
CREATE INDEX IF NOT EXISTS idx_marketing_sends_booking_id           ON public.marketing_sends(booking_id);
-- provider_message_id already has a UNIQUE index from the constraint above

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. email_suppression_list — hard bounces, complaints, manual suppress
--    Members read; owner/admin write.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.email_suppression_list (
  id         uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  studio_id  uuid        NOT NULL REFERENCES public.studios(id) ON DELETE CASCADE,
  email      text        NOT NULL,
  reason     text        NOT NULL CHECK (reason IN ('bounce', 'complaint', 'manual', 'unsubscribe')),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_suppression_studio_email UNIQUE (studio_id, email)
);

COMMENT ON TABLE  public.email_suppression_list       IS 'Suppressed email addresses per studio — populated by bounces, complaints, or manual entry.';
COMMENT ON COLUMN public.email_suppression_list.email IS 'PII:L3 — suppressed email, confidential';

ALTER TABLE public.email_suppression_list ENABLE ROW LEVEL SECURITY;

CREATE POLICY "email_suppression_list_select" ON public.email_suppression_list
  FOR SELECT USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "email_suppression_list_insert" ON public.email_suppression_list
  FOR INSERT WITH CHECK (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid() AND role IN ('owner', 'admin')
    )
  );

CREATE POLICY "email_suppression_list_delete" ON public.email_suppression_list
  FOR DELETE USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members
      WHERE user_id = auth.uid() AND role IN ('owner', 'admin')
    )
  );

-- Indexes
CREATE INDEX IF NOT EXISTS idx_suppression_studio_email ON public.email_suppression_list(studio_id, email);

-- ─────────────────────────────────────────────────────────────────────────────
-- 4. referral_programs — one-row-per-studio program rules
--    PK = studio_id (enforces one-per-studio naturally).
--    Members read; owner/admin write.
--    Audit trigger: yes.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.referral_programs (
  studio_id              uuid        PRIMARY KEY REFERENCES public.studios(id) ON DELETE CASCADE,
  referrer_reward_type   text        CHECK (referrer_reward_type IN ('credit', 'percentage', 'free_session', 'none')),
  referrer_reward_value  numeric,    -- cents for credit; percent value for percentage
  referred_reward_type   text        CHECK (referred_reward_type IN ('discount_fixed', 'discount_percent', 'none')),
  referred_reward_value  numeric,
  trigger                text        NOT NULL DEFAULT 'booking_completed'
                                     CHECK (trigger IN ('booking_completed', 'first_booking', 'payment_settled')),
  expiry_days            int         NOT NULL DEFAULT 90,
  is_active              boolean     NOT NULL DEFAULT false,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.referral_programs IS 'Per-studio referral program reward rules. One row per studio.';

ALTER TABLE public.referral_programs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "referral_programs_select" ON public.referral_programs
  FOR SELECT USING (
    studio_id IN (
      SELECT studio_id FROM public.studio_members WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "referral_programs_insert" ON public.referral_programs
  FOR INSERT WITH CHECK (
