DROP TRIGGER IF EXISTS trg_audit_referral_programs ON public.referral_programs;
CREATE TRIGGER trg_audit_referral_programs
  AFTER INSERT OR UPDATE OR DELETE ON public.referral_programs
  FOR EACH ROW EXECUTE FUNCTION fn_referral_programs_audit();

-- ─────────────────────────────────────────────────────────────────────────────
