  ELSE                         v_row := row_to_json(NEW)::jsonb; v_old_row := row_to_json(OLD)::jsonb;
  END IF;
  INSERT INTO audit_log (action, actor_id, studio_id, target_type, target_id, details, created_at)
  VALUES (
    'marketing_waitlist_rules.' || lower(TG_OP),
    auth.uid(),
    (v_row->>'studio_id')::uuid,
    'marketing_waitlist_rules',
    v_row->>'studio_id',
    CASE TG_OP
      WHEN 'INSERT' THEN jsonb_build_object('new', v_row)
      WHEN 'UPDATE' THEN jsonb_build_object('old', v_old_row, 'new', v_row)
      WHEN 'DELETE' THEN jsonb_build_object('old', v_row)
    END,
    now()
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS trg_audit_marketing_waitlist_rules ON public.marketing_waitlist_rules;
CREATE TRIGGER trg_audit_marketing_waitlist_rules
  AFTER INSERT OR UPDATE OR DELETE ON public.marketing_waitlist_rules
  FOR EACH ROW EXECUTE FUNCTION fn_marketing_waitlist_rules_audit();

