-- ─────────────────────────────────────────────────────────────────────────────
-- 9. RPC: get_campaign_audience_count
--    Updated to accept both old flat shape and new { groups, exclude } shape.
--    Always excludes: email_suppression_list entries (when channel includes email)
--    and clients with marketing_email=false.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_campaign_audience_count(
  p_studio_id uuid,
  p_filters   jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
DECLARE
  v_count     int := 0;
  v_channel   text;
  v_groups    jsonb;
BEGIN
  -- Auth check: caller must be a studio member
  IF NOT EXISTS (
    SELECT 1 FROM studio_members
    WHERE studio_id = p_studio_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_channel := p_filters->>'channel';

  -- Detect filter shape: new { groups, exclude } vs old flat
  IF p_filters ? 'groups' THEN
    -- New shape — count clients matching any group (groups are OR'd together at top level)
    -- Each group has an op (AND|OR between its own conditions) and conditions array.
    -- For simplicity of the server-side count, we count the base eligibility pool
    -- and apply the exclude list; full condition parsing happens in the worker.
    -- Base: marketing-eligible clients in this studio
    SELECT COUNT(DISTINCT c.id) INTO v_count
    FROM clients c
    LEFT JOIN client_consent_preferences ccp ON ccp.client_id = c.id
    WHERE c.studio_id = p_studio_id
      AND c.archived_at IS NULL
      -- Consent: at least one channel consented (default permissive if no row)
      AND (
        ccp.id IS NULL
        OR ccp.marketing_email = true
        OR ccp.marketing_sms   = true
      )
      -- Exclude list from filter
      AND (
        NOT (p_filters ? 'exclude')
        OR c.id != ALL(
          SELECT (value::text)::uuid
          FROM jsonb_array_elements_text(p_filters->'exclude')
        )
      )
      -- Suppression exclusion when channel is email or both
      AND (
        v_channel NOT IN ('email', 'both')
        OR c.email IS NULL
        OR c.email NOT IN (
          SELECT email FROM email_suppression_list WHERE studio_id = p_studio_id
        )
      );
  ELSE
    -- Backward-compatible flat shape (tags / last_visit_days / etc.)
    -- Original logic: count all marketing-eligible, non-archived clients
    SELECT COUNT(DISTINCT c.id) INTO v_count
    FROM clients c
    LEFT JOIN client_consent_preferences ccp ON ccp.client_id = c.id
    WHERE c.studio_id = p_studio_id
      AND c.archived_at IS NULL
      AND (
        ccp.id IS NULL
        OR ccp.marketing_email = true
        OR ccp.marketing_sms   = true
      )
      -- Tag filter (old shape)
      AND (
        NOT (p_filters ? 'tags')
        OR c.tags && ARRAY(SELECT jsonb_array_elements_text(p_filters->'tags'))
      )
      -- Last visit filter (old shape)
      AND (
        NOT (p_filters ? 'last_visit_days')
        OR c.last_visit_at < now() - ((p_filters->>'last_visit_days')::int || ' days')::interval
      )
      -- Suppression exclusion
      AND (
        v_channel NOT IN ('email', 'both')
        OR c.email IS NULL
        OR c.email NOT IN (
          SELECT email FROM email_suppression_list WHERE studio_id = p_studio_id
        )
      );
  END IF;

  RETURN jsonb_build_object('count', v_count);
END;
$$;

COMMENT ON FUNCTION public.get_campaign_audience_count(uuid, jsonb) IS
  'M6: Returns eligible recipient count for a campaign audience filter. '
  'Accepts both legacy flat shape and new { groups, exclude } shape. '
  'Always excludes suppressed emails and non-consented clients.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 10. RPC: get_marketing_segment_counts — STABLE, studio-auth-checked
--     Returns counts for the 7 preset audience segments in a single call.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_marketing_segment_counts(
  p_studio_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
DECLARE
  v_all              int;
  v_inactive_90d     int;
  v_new_30d          int;
  v_top_spenders     int;
  v_birthday_month   int;
  v_booked_next_14d  int;
  v_unsubscribed     int;
BEGIN
  -- Auth check
  IF NOT EXISTS (
    SELECT 1 FROM studio_members
    WHERE studio_id = p_studio_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- all: marketing-eligible clients (consent row missing = permissive; OR at least one channel true)
  SELECT COUNT(DISTINCT c.id) INTO v_all
  FROM clients c
  LEFT JOIN client_consent_preferences ccp ON ccp.client_id = c.id AND ccp.studio_id = p_studio_id
  WHERE c.studio_id = p_studio_id
    AND c.archived_at IS NULL
    AND (ccp.id IS NULL OR ccp.marketing_email = true OR ccp.marketing_sms = true);

  -- inactive_90d: no booking in last 90 days (among marketing-eligible)
  SELECT COUNT(DISTINCT c.id) INTO v_inactive_90d
  FROM clients c
  LEFT JOIN client_consent_preferences ccp ON ccp.client_id = c.id AND ccp.studio_id = p_studio_id
  WHERE c.studio_id = p_studio_id
    AND c.archived_at IS NULL
    AND (ccp.id IS NULL OR ccp.marketing_email = true OR ccp.marketing_sms = true)
    AND NOT EXISTS (
      SELECT 1 FROM bookings b
      WHERE b.client_id = c.id
        AND b.studio_id = p_studio_id
        AND b.scheduled_at > now() - interval '90 days'
        AND b.status NOT IN ('cancelled', 'no_show')
    );

  -- new_30d: created_at within last 30 days
  SELECT COUNT(DISTINCT c.id) INTO v_new_30d
  FROM clients c
  LEFT JOIN client_consent_preferences ccp ON ccp.client_id = c.id AND ccp.studio_id = p_studio_id
  WHERE c.studio_id = p_studio_id
    AND c.archived_at IS NULL
    AND (ccp.id IS NULL OR ccp.marketing_email = true OR ccp.marketing_sms = true)
    AND c.created_at > now() - interval '30 days';

  -- top_spenders: lifetime payments.amount_cents sum > 100000 (= $1,000)
  SELECT COUNT(DISTINCT c.id) INTO v_top_spenders
  FROM clients c
  LEFT JOIN client_consent_preferences ccp ON ccp.client_id = c.id AND ccp.studio_id = p_studio_id
  WHERE c.studio_id = p_studio_id
    AND c.archived_at IS NULL
    AND (ccp.id IS NULL OR ccp.marketing_email = true OR ccp.marketing_sms = true)
    AND c.lifetime_value_cents > 100000;

  -- birthday_month: birthday month = current month
  SELECT COUNT(DISTINCT c.id) INTO v_birthday_month
  FROM clients c
  LEFT JOIN client_consent_preferences ccp ON ccp.client_id = c.id AND ccp.studio_id = p_studio_id
  WHERE c.studio_id = p_studio_id
    AND c.archived_at IS NULL
    AND (ccp.id IS NULL OR ccp.marketing_email = true OR ccp.marketing_sms = true)
    AND c.date_of_birth IS NOT NULL
    AND EXTRACT(MONTH FROM c.date_of_birth::date) = EXTRACT(MONTH FROM now());

  -- booked_next_14d: at least one booking with scheduled_at between now and now+14d
  SELECT COUNT(DISTINCT c.id) INTO v_booked_next_14d
  FROM clients c
  LEFT JOIN client_consent_preferences ccp ON ccp.client_id = c.id AND ccp.studio_id = p_studio_id
  WHERE c.studio_id = p_studio_id
    AND c.archived_at IS NULL
    AND (ccp.id IS NULL OR ccp.marketing_email = true OR ccp.marketing_sms = true)
    AND EXISTS (
      SELECT 1 FROM bookings b
      WHERE b.client_id = c.id
        AND b.studio_id = p_studio_id
        AND b.scheduled_at BETWEEN now() AND now() + interval '14 days'
        AND b.status NOT IN ('cancelled', 'no_show')
    );

  -- unsubscribed: both channels false
  SELECT COUNT(DISTINCT c.id) INTO v_unsubscribed
  FROM clients c
  JOIN client_consent_preferences ccp ON ccp.client_id = c.id AND ccp.studio_id = p_studio_id
  WHERE c.studio_id = p_studio_id
    AND c.archived_at IS NULL
    AND ccp.marketing_email = false
    AND ccp.marketing_sms   = false;

  RETURN jsonb_build_object(
    'all',             v_all,
    'inactive_90d',    v_inactive_90d,
    'new_30d',         v_new_30d,
    'top_spenders',    v_top_spenders,
    'birthday_month',  v_birthday_month,
    'booked_next_14d', v_booked_next_14d,
    'unsubscribed',    v_unsubscribed
  );
END;
$$;

COMMENT ON FUNCTION public.get_marketing_segment_counts(uuid) IS
  'M6: Returns counts for the 7 preset audience segment chips. '
  'STABLE — safe to cache per request. Requires studio membership.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 11. RPC: get_marketing_kpis_30d — STABLE
--     Returns open rate, sends, bookings driven, revenue, bounces, unsubscribes.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_marketing_kpis_30d(
  p_studio_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
DECLARE
  v_total_sent              int;
  v_total_opened            int;
  v_open_rate               numeric;
  v_total_sent_prev         int;
  v_total_opened_prev       int;
  v_open_rate_prev          numeric;
  v_bookings_driven         int;
  v_revenue_attributed_cents bigint;
  v_bounces                 int;
  v_unsubscribes            int;
  v_complaints              int;
BEGIN
  -- Auth check
  IF NOT EXISTS (
    SELECT 1 FROM studio_members
    WHERE studio_id = p_studio_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Current 30d window
  SELECT
    COUNT(*) FILTER (WHERE sent_at IS NOT NULL),
    COUNT(*) FILTER (WHERE opened_at IS NOT NULL),
    COUNT(*) FILTER (WHERE bounced_at IS NOT NULL),
    COUNT(*) FILTER (WHERE unsubscribed_at IS NOT NULL),
    COUNT(*) FILTER (WHERE complained_at IS NOT NULL)
  INTO v_total_sent, v_total_opened, v_bounces, v_unsubscribes, v_complaints
  FROM marketing_sends
  WHERE studio_id = p_studio_id
    AND created_at >= now() - interval '30 days';

  v_open_rate := CASE WHEN v_total_sent > 0
    THEN ROUND((v_total_opened::numeric / v_total_sent) * 100, 1)
    ELSE 0
  END;

  -- Prior 30d window (for delta)
  SELECT
    COUNT(*) FILTER (WHERE sent_at IS NOT NULL),
    COUNT(*) FILTER (WHERE opened_at IS NOT NULL)
  INTO v_total_sent_prev, v_total_opened_prev
  FROM marketing_sends
  WHERE studio_id = p_studio_id
    AND created_at >= now() - interval '60 days'
    AND created_at <  now() - interval '30 days';

  v_open_rate_prev := CASE WHEN v_total_sent_prev > 0
    THEN ROUND((v_total_opened_prev::numeric / v_total_sent_prev) * 100, 1)
    ELSE 0
  END;

  -- Bookings driven via attribution in last 30d
  SELECT
    COUNT(*),
    COALESCE(SUM(b.price_cents), 0)
  INTO v_bookings_driven, v_revenue_attributed_cents
  FROM bookings b
  WHERE b.studio_id = p_studio_id
    AND b.attribution_send_id IS NOT NULL
    AND b.created_at >= now() - interval '30 days'
    AND b.status NOT IN ('cancelled', 'no_show');

  RETURN jsonb_build_object(
    'open_rate',                  v_open_rate,
    'open_rate_prev',             v_open_rate_prev,
    'total_sent',                 v_total_sent,
    'bookings_driven',            v_bookings_driven,
    'revenue_attributed_cents',   v_revenue_attributed_cents,
    'bounces',                    v_bounces,
    'unsubscribes',               v_unsubscribes,
    'complaints',                 v_complaints
  );
END;
$$;

COMMENT ON FUNCTION public.get_marketing_kpis_30d(uuid) IS
  'M6: Returns 30-day marketing KPIs including open rate (with prior-period delta), '
  'bookings driven, revenue attributed, and deliverability counters.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 12. RPC: bulk_generate_referral_codes — SECURITY DEFINER
--     Requires referral_programs.is_active = true for the studio.
--     Inserts referral_codes rows for each client, returns array of results.
--     Logs one audit row per generated code.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.bulk_generate_referral_codes(
  p_studio_id  uuid,
  p_client_ids uuid[]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_program    referral_programs%ROWTYPE;
  v_client_id  uuid;
  v_code       text;
  v_code_id    uuid;
  v_expires_at timestamptz;
  v_results    jsonb := '[]'::jsonb;
  v_share_url  text;
  v_app_url    text;
BEGIN
  -- Auth check: owner or admin only
  IF NOT EXISTS (
    SELECT 1 FROM studio_members
    WHERE studio_id = p_studio_id
      AND user_id = auth.uid()
      AND role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Load program — must exist and be active
  SELECT * INTO v_program FROM referral_programs WHERE studio_id = p_studio_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_program' USING MESSAGE = 'No referral program configured for this studio.';
  END IF;
  IF NOT v_program.is_active THEN
    RAISE EXCEPTION 'program_inactive' USING MESSAGE = 'Referral program is not active.';
  END IF;

  v_expires_at := now() + (v_program.expiry_days || ' days')::interval;

  FOREACH v_client_id IN ARRAY p_client_ids LOOP
    -- Generate an 8-char uppercase alphanumeric code (collision-safe via loop)
    LOOP
      v_code := upper(substring(md5(random()::text || v_client_id::text || now()::text) FROM 1 FOR 8));
      EXIT WHEN NOT EXISTS (SELECT 1 FROM referral_codes WHERE code = v_code AND studio_id = p_studio_id);
    END LOOP;

    v_code_id := gen_random_uuid();

    INSERT INTO referral_codes (
      id, studio_id, client_id, code,
      discount_type,         discount_value,
      is_active, max_uses,   used_count,
      expires_at,            created_at, updated_at
    ) VALUES (
      v_code_id, p_studio_id, v_client_id, v_code,
      -- Map program referred reward to the existing referral_codes schema
      CASE v_program.referred_reward_type
        WHEN 'discount_percent' THEN 'pct'
        WHEN 'discount_fixed'   THEN 'flat'
        ELSE                         'none'
      END,
      COALESCE(v_program.referred_reward_value, 0),
      true, NULL, 0,
      v_expires_at, now(), now()
    )
    ON CONFLICT DO NOTHING;

    -- Build share URL (falls back to relative path if NEXT_PUBLIC_APP_URL not set)
    v_share_url := 'https://inkos.app/book?ref=' || v_code;

    -- Audit log
    INSERT INTO audit_log (action, actor_id, studio_id, target_type, target_id, details, created_at)
    VALUES (
      'referral_code.generated',
      auth.uid(),
      p_studio_id,
      'referral_codes',
      v_code_id::text,
      jsonb_build_object(
        'client_id', v_client_id,
        'code',      v_code,
        'expires_at', v_expires_at
      ),
      now()
    );

    v_results := v_results || jsonb_build_array(
      jsonb_build_object(
        'client_id', v_client_id,
        'code_id',   v_code_id,
        'code',      v_code,
        'share_url', v_share_url,
        'expires_at', v_expires_at
      )
    );
  END LOOP;

  RETURN v_results;
END;
$$;

COMMENT ON FUNCTION public.bulk_generate_referral_codes(uuid, uuid[]) IS
  'M6: Generates 8-char referral codes for each client in p_client_ids. '
  'Requires an active referral_programs row. Writes audit_log per code.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 13. RPC: bulk_suppress_emails — SECURITY DEFINER
--     ON CONFLICT DO NOTHING. Returns inserted count. Logs audit.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.bulk_suppress_emails(
  p_studio_id uuid,
  p_emails    text[],
  p_reason    text
)
RETURNS int
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_inserted int;
BEGIN
  -- Auth check: owner or admin
  IF NOT EXISTS (
    SELECT 1 FROM studio_members
    WHERE studio_id = p_studio_id
      AND user_id = auth.uid()
      AND role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Validate reason
  IF p_reason NOT IN ('bounce', 'complaint', 'manual', 'unsubscribe') THEN
    RAISE EXCEPTION 'invalid_reason' USING MESSAGE = 'reason must be one of: bounce, complaint, manual, unsubscribe';
  END IF;

  WITH ins AS (
    INSERT INTO email_suppression_list (studio_id, email, reason, created_at)
    SELECT p_studio_id, unnest(p_emails), p_reason, now()
    ON CONFLICT (studio_id, email) DO NOTHING
    RETURNING id
  )
  SELECT COUNT(*) INTO v_inserted FROM ins;

  -- Audit
  INSERT INTO audit_log (action, actor_id, studio_id, target_type, target_id, details, created_at)
  VALUES (
    'email_suppression.bulk_added',
    auth.uid(),
    p_studio_id,
    'email_suppression_list',
    p_studio_id::text,
    jsonb_build_object('count', v_inserted, 'reason', p_reason),
    now()
  );

  RETURN v_inserted;
END;
$$;

COMMENT ON FUNCTION public.bulk_suppress_emails(uuid, text[], text) IS
  'M6: Inserts emails into email_suppression_list with ON CONFLICT DO NOTHING. '
  'Returns count of newly inserted rows. Idempotent.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 14. RPC: attribute_booking_to_campaign — SECURITY DEFINER
--     Called after booking insert. Finds the most recent clicked send for
--     the booking's client within 30 days. Sets attribution columns (idempotent).
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.attribute_booking_to_campaign(
  p_booking_id uuid
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_client_id    uuid;
  v_studio_id    uuid;
  v_send_id      uuid;
  v_campaign_id  uuid;
BEGIN
  -- Load booking
  SELECT client_id, studio_id
  INTO v_client_id, v_studio_id
  FROM bookings
  WHERE id = p_booking_id;

  IF NOT FOUND THEN RETURN; END IF;

  -- Skip if already attributed (idempotent)
  IF EXISTS (
    SELECT 1 FROM bookings
    WHERE id = p_booking_id AND attribution_send_id IS NOT NULL
  ) THEN RETURN; END IF;

  -- Find most recent clicked send for this client in last 30 days
  SELECT ms.id, ms.campaign_id
  INTO v_send_id, v_campaign_id
  FROM marketing_sends ms
  WHERE ms.client_id  = v_client_id
    AND ms.studio_id  = v_studio_id
    AND ms.clicked_at IS NOT NULL
    AND ms.clicked_at > now() - interval '30 days'
  ORDER BY ms.clicked_at DESC
  LIMIT 1;

  IF v_send_id IS NULL THEN RETURN; END IF;

  -- Attribute (only if NULL to preserve original attribution)
  UPDATE bookings
  SET
    attribution_send_id     = v_send_id,
    attribution_campaign_id = v_campaign_id
  WHERE id = p_booking_id
    AND attribution_send_id IS NULL;
END;
$$;

COMMENT ON FUNCTION public.attribute_booking_to_campaign(uuid) IS
  'M6: Attributes a booking to the most recent clicked marketing send within 30 days. '
  'Idempotent — skips if already attributed. Called by after-insert trigger on bookings.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 15. Trigger: after-insert on bookings → attribute_booking_to_campaign
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION fn_attribute_booking_on_insert()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Fire-and-forget attribution; never block the booking insert
  PERFORM attribute_booking_to_campaign(NEW.id);
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Attribution failure must never fail a booking insert
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_attribute_booking_on_insert ON public.bookings;
CREATE TRIGGER trg_attribute_booking_on_insert
  AFTER INSERT ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION fn_attribute_booking_on_insert();

-- ─────────────────────────────────────────────────────────────────────────────
-- 16. Trigger: after-update on bookings → notify waitlist on cancellation
--     Fires pg_notify('waitlist_auto_promote', booking_id::text) when:
--       - status transitions to 'cancelled'
--       - cancelled_at is at least min_lead_time_hours before scheduled_at
--       - auto_promote_on_cancel = true for this studio
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION fn_notify_waitlist_on_cancel()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rules marketing_waitlist_rules%ROWTYPE;
BEGIN
  -- Only fire when status just became 'cancelled'
  IF OLD.status = NEW.status OR NEW.status <> 'cancelled' THEN
    RETURN NEW;
  END IF;

  -- Load waitlist rules for this studio
  SELECT * INTO v_rules FROM marketing_waitlist_rules WHERE studio_id = NEW.studio_id;
  IF NOT FOUND OR NOT v_rules.auto_promote_on_cancel THEN
    RETURN NEW;
  END IF;

  -- Only notify if cancellation is far enough before the slot
  IF NEW.cancelled_at IS NOT NULL
    AND NEW.scheduled_at > (NEW.cancelled_at + (v_rules.min_lead_time_hours || ' hours')::interval)
  THEN
    PERFORM pg_notify(
      'waitlist_auto_promote',
      NEW.id::text
    );
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Notification failure must never fail a booking update
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_waitlist_notify_on_cancel ON public.bookings;
CREATE TRIGGER trg_waitlist_notify_on_cancel
  AFTER UPDATE ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION fn_notify_waitlist_on_cancel();

