input.content:
/**
 * Resend delivery-event webhook handler.
 *
 * Handles delivery lifecycle events for marketing_sends:
 *   email.sent · email.delivered · email.opened · email.clicked
 *   email.bounced · email.complained · email.delivery_delayed
 *
 * Security:
 *   - Svix signature verification via svix-id / svix-timestamp / svix-signature headers
 *   - timingSafeEqual for final comparison (project rule)
 *   - HMAC-SHA256 over `${svix-id}.${svix-timestamp}.${rawBody}`
 *   - Idempotent: duplicate event IDs are ignored (UPDATE is a no-op if timestamp already set)
 *
 * Configure in Resend dashboard:
 *   Settings → Webhooks → Add webhook URL: {NEXT_PUBLIC_APP_URL}/api/webhooks/resend
 *
 * Required env var (optional in dev):
 *   RESEND_WEBHOOK_SECRET — signing secret from Resend dashboard (NOT the API key)
 *
 * Returns 200 on success, idempotent replay, or unsupported event type.
 * Returns 503 when RESEND_WEBHOOK_SECRET is unset (signals ops to fix config; provider retries).
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createHmac, timingSafeEqual } from 'crypto'
import { z } from 'zod'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export const dynamic = 'force-dynamic'

// ─── Zod schema for Resend delivery event envelope ────────────────────────────

const ResendEventSchema = z.object({
  type: z.enum([
    'email.sent',
    'email.delivered',
    'email.opened',
    'email.clicked',
    'email.bounced',
    'email.complained',
    'email.delivery_delayed',
  ]),
  data: z.object({
    email_id: z.string(),         // Resend message ID — matches marketing_sends.provider_message_id
    to: z.array(z.string()).optional(),
    from: z.string().optional(),
    subject: z.string().optional(),
    // bounce / complaint specifics
    bounce: z.object({ message: z.string().optional() }).optional(),
  }),
})

type ResendEvent = z.infer<typeof ResendEventSchema>

// ─── Svix signature verification ──────────────────────────────────────────────

/**
 * Verifies a Svix-signed webhook request.
 * Svix signs: `${svix-id}.${svix-timestamp}.${rawBody}` with HMAC-SHA256.
 * The secret is base64-encoded; strip the `whsec_` prefix before decoding.
 *
 * Reference: https://docs.svix.com/receiving/verifying-payloads/how
 */
function verifySvixSignature(
  rawBody: string,
  headers: Headers,
  secret: string,
): boolean {
  const msgId        = headers.get('svix-id')
  const msgTimestamp = headers.get('svix-timestamp')
  const msgSignature = headers.get('svix-signature')

  if (!msgId || !msgTimestamp || !msgSignature) return false

  // Reject messages older than 5 minutes
  const tsSeconds = parseInt(msgTimestamp, 10)
  if (isNaN(tsSeconds) || Math.abs(Date.now() / 1000 - tsSeconds) > 300) return false

  // Decode base64 secret (strip whsec_ prefix if present)
  const cleanSecret = secret.startsWith('whsec_') ? secret.slice(6) : secret
  let secretBytes: Buffer
  try {
    secretBytes = Buffer.from(cleanSecret, 'base64')
  } catch {
    return false
  }

  // Compute expected signature
  const toSign    = `${msgId}.${msgTimestamp}.${rawBody}`
  const expected  = createHmac('sha256', secretBytes).update(toSign).digest('base64')

  // The Svix header can contain multiple space-separated `v1,<sig>` entries
  const signatures = msgSignature.split(' ')
  for (const sigEntry of signatures) {
    const parts = sigEntry.split(',')
    if (parts.length !== 2 || parts[0] !== 'v1') continue
    const incoming = parts[1]
    if (!incoming) continue

    try {
      const expectedBuf = Buffer.from(expected, 'base64')
      const incomingBuf = Buffer.from(incoming, 'base64')

      if (
        expectedBuf.length === incomingBuf.length &&
        timingSafeEqual(expectedBuf, incomingBuf)
      ) {
        return true
      }
    } catch {
      continue
    }
  }

  return false
}

// ─── Event → column mapping ────────────────────────────────────────────────────

const EVENT_TIMESTAMP_COLUMN: Partial<Record<ResendEvent['type'], string>> = {
  'email.opened':  'opened_at',
  'email.clicked': 'clicked_at',
  'email.bounced': 'bounced_at',
  'email.complained': 'complained_at',
  'email.delivery_delayed': null as unknown as string,  // no dedicated column — log only
}

// ─── POST handler ─────────────────────────────────────────────────────────────

export async function POST(req: NextRequest): Promise<NextResponse> {
  // Config check — 503 signals provider to retry
  const secret = process.env.RESEND_WEBHOOK_SECRET
  if (!secret) {
    logger.error({ webhook: 'resend' }, 'RESEND_WEBHOOK_SECRET not configured')
    return new NextResponse('Webhook not configured', { status: 503 })
  }

  // Rate-limit by IP (protects against replay flood before signature check)
  const ip    = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown'
  const limit = await apiRatelimit.limit(ip)
  if (!limit.success) {
    logger.warn({ ip, webhook: 'resend' }, 'rate limit exceeded on resend webhook')
    return new NextResponse('Too many requests', { status: 429 })
  }

  // Read raw body (must happen before any .json() call)
  const rawBody = await req.text()

  // Verify Svix signature
  if (!verifySvixSignature(rawBody, req.headers, secret)) {
    logger.warn({ ip }, 'resend webhook: signature verification failed')
    return new NextResponse('Invalid signature', { status: 401 })
  }

  // Parse event envelope
  let parsed: ReturnType<typeof ResendEventSchema.safeParse>
  try {
    parsed = ResendEventSchema.safeParse(JSON.parse(rawBody))
  } catch {
    logger.warn({ webhook: 'resend' }, 'resend webhook: JSON parse error')
    return new NextResponse('Bad request', { status: 400 })
  }

  if (!parsed.success) {
    // Unsupported event type — return 200 so Resend doesn't retry
    logger.info(
      { issues: parsed.error.issues, webhook: 'resend' },
      'resend webhook: unsupported or unknown event — ignoring',
    )
    return NextResponse.json({ ok: true, ignored: true })
  }

  const event    = parsed.data
  const emailId  = event.data.email_id
  const eventLog = { eventType: event.type, emailId, webhook: 'resend' }

  const supabase = createServiceRoleClient()

  // Look up the marketing_sends row by provider_message_id
  const { data: sendRow, error: fetchErr } = await supabase
    .from('marketing_sends')
    .select('id, studio_id, recipient_email, bounced_at, complained_at')
    .eq('provider_message_id', emailId)
    .maybeSingle()

  if (fetchErr) {
    logger.error({ ...eventLog, err: fetchErr.message }, 'resend webhook: DB fetch error')
    // Return 200 to prevent Resend from retrying on infra errors we can't fix here
    return NextResponse.json({ ok: false, error: 'db_error' })
  }

  if (!sendRow) {
    // Not a marketing send we track (could be a transactional email)
    logger.debug({ ...eventLog }, 'resend webhook: send row not found — skipping')
    return NextResponse.json({ ok: true, ignored: true })
  }

  // ── Route by event type ──────────────────────────────────────────────────

  if (event.type === 'email.bounced' || event.type === 'email.complained') {
    await handleDeliverabilityEvent(supabase, sendRow, event)
    return NextResponse.json({ ok: true })
  }

  if (event.type === 'email.delivery_delayed') {
    // No timestamp column — log for ops visibility, nothing to update
    logger.info({ ...eventLog, sendId: sendRow.id }, 'resend webhook: delivery delayed')
    return NextResponse.json({ ok: true })
  }

  // email.sent, email.delivered, email.opened, email.clicked
  const column = EVENT_TIMESTAMP_COLUMN[event.type]
  if (column) {
    const { error: updErr } = await supabase
      .from('marketing_sends')
      .update({ [column]: new Date().toISOString() })
      .eq('id', sendRow.id)
      .is(column, null)  // idempotent — only set once

    if (updErr) {
      logger.error({ ...eventLog, sendId: sendRow.id, err: updErr.message }, 'resend webhook: update error')
    } else {
      logger.info({ ...eventLog, sendId: sendRow.id }, 'resend webhook: timestamp updated')
    }
  }

  return NextResponse.json({ ok: true })
}

// ─── handleDeliverabilityEvent ────────────────────────────────────────────────

type SendRow = {
  id: string
  studio_id: string
  recipient_email: string | null
  bounced_at: string | null
  complained_at: string | null
}

async function handleDeliverabilityEvent(
  supabase: ReturnType<typeof createServiceRoleClient>,
  sendRow: SendRow,
  event: ResendEvent,
): Promise<void> {
  const isBounce    = event.type === 'email.bounced'
  const col         = isBounce ? 'bounced_at' : 'complained_at'
  const reason: 'bounce' | 'complaint' = isBounce ? 'bounce' : 'complaint'
  const eventLog    = { eventType: event.type, sendId: sendRow.id, webhook: 'resend' }

  // 1. Update marketing_sends timestamp (idempotent)
  const { error: tsErr } = await supabase
    .from('marketing_sends')
    .update({ [col]: new Date().toISOString() })
    .eq('id', sendRow.id)
    .is(col, null)

  if (tsErr) {
    logger.error({ ...eventLog, err: tsErr.message }, 'resend webhook: timestamp update error')
  }

  // 2. Insert into email_suppression_list (idempotent — ON CONFLICT DO NOTHING)
  const email = sendRow.recipient_email
  if (email) {
    const { error: suppErr } = await supabase
      .from('email_suppression_list')
      .insert({
        studio_id:  sendRow.studio_id,
        email,
        reason,
        created_at: new Date().toISOString(),
      })
      // ON CONFLICT (studio_id, email) → ignore duplicate
      .select('id')
      .limit(1)

    if (suppErr && suppErr.code !== '23505') {
      logger.error({ ...eventLog, err: suppErr.message }, 'resend webhook: suppression insert error')
    } else {
      logger.info({ ...eventLog, email, reason }, 'resend webhook: email suppressed')
    }
  }
}

import type { AdminClient } from '../client'
