  // 2. Referral codes — 3 codes
  // ──────────────────────────────────────────────────────────────────────────
  const codes = [
    { code: 'FRIEND15', discount: 15, discountType: 'pct' as const, reward: 2000, rewardType: 'flat' as const, clientIdx: 0 },
