  ]
  const codeRows = codes.map((c) => ({
    id: detId('referral_code', c.code),
    studio_id: ctx.studioId,
    client_id: ctx.clientIds[c.clientIdx]!,
    code: c.code,
    discount_type: c.discountType,
    discount_value: c.discount,
    referrer_reward_type: c.rewardType,
    referrer_reward_value: c.reward,
    max_uses: 50,
    uses_count: 4,
    is_active: true,
    expires_at: new Date(now.getTime() + 90 * 86400_000).toISOString(),
  }))
  const { error: codeErr } = await tolerantUpsert(sb, 'referral_codes', codeRows, 'id')
  if (codeErr) {
    log.module('marketing', 0, `referral_codes (skipped: ${codeErr.message})`)
  } else {
    log.module('marketing', codeRows.length, 'referral_codes')
  }

  // ──────────────────────────────────────────────────────────────────────────
  // 3. Referral redemptions — 3 applied
  // ──────────────────────────────────────────────────────────────────────────
  const redemptionRows = Array.from({ length: 3 }, (_, i) => ({
    id: detId('referral_redemption', `${i}`),
    studio_id: ctx.studioId,
    code_id: codeRows[i % codeRows.length]!.id,
    referrer_client_id: ctx.clientIds[i]!,
    referred_client_id: ctx.clientIds[i + 10]!,
    booking_id: ctx.bookingIds[i]!,
    discount_amount_cents: 3000,
    referrer_reward_cents: 1500,
    status: 'applied' as const,
  }))
  const { error: redErr } = await tolerantUpsert(sb, 'referral_redemptions', redemptionRows, 'id')
  if (redErr) {
    log.module('marketing', 0, `referral_redemptions (skipped: ${redErr.message})`)
  } else {
    log.module('marketing', redemptionRows.length, 'referral_redemptions')
  }

  // ──────────────────────────────────────────────────────────────────────────
  // 4. referral_programs — 1 active program for the demo studio
  // ──────────────────────────────────────────────────────────────────────────
  const referralProgram = {
    studio_id:             ctx.studioId,
    referrer_reward_type:  'credit',
    referrer_reward_value: 2500,   // $25 credit (cents)
    referred_reward_type:  'discount_fixed',
    referred_reward_value: 2500,   // $25 off first booking
    trigger:               'booking_completed',
    expiry_days:           90,
    is_active:             true,
  }
  const { error: rpErr } = await tolerantUpsert(
    sb, 'referral_programs', [referralProgram], 'studio_id',
  )
  if (rpErr) {
    log.module('marketing', 0, `referral_programs (skipped: ${rpErr.message})`)
  } else {
    log.module('marketing', 1, 'referral_programs')
  }

  // ──────────────────────────────────────────────────────────────────────────
  // 5. audience_segments — 3 saved segments
  // ──────────────────────────────────────────────────────────────────────────
  const segments = [
    {
      id: detId('segment', 'inactive-vips'),
      studio_id:  ctx.studioId,
      name:       'Inactive VIPs',
      filter: asJson({
        groups: [
          {
            op: 'AND',
            conditions: [
              { field: 'tags',           op: 'contains',  value: 'VIP' },
              { field: 'last_visit_days', op: 'gt',        value: 90 },
            ],
          },
        ],
        exclude: [],
      }),
    },
    {
      id: detId('segment', 'birthday-this-month'),
      studio_id:  ctx.studioId,
      name:       'Birthdays this month',
      filter: asJson({
        groups: [
          {
            op: 'AND',
            conditions: [
              { field: 'birthday_month', op: 'eq', value: 'current' },
            ],
          },
        ],
        exclude: [],
      }),
    },
    {
      id: detId('segment', 'new-clients-30d'),
      studio_id:  ctx.studioId,
      name:       'New clients — last 30 days',
      filter: asJson({
        groups: [
          {
            op: 'AND',
            conditions: [
              { field: 'created_days', op: 'lte', value: 30 },
            ],
          },
        ],
        exclude: [],
      }),
    },
  ]
  const { error: segErr } = await tolerantUpsert(sb, 'audience_segments', segments, 'id')
  if (segErr) {
    log.module('marketing', 0, `audience_segments (skipped: ${segErr.message})`)
  } else {
    log.module('marketing', segments.length, 'audience_segments')
  }

  // ──────────────────────────────────────────────────────────────────────────
  // 6. marketing_sends — 50 sends mixing opened / clicked / bounced states
  // ──────────────────────────────────────────────────────────────────────────
  type SendState = 'sent' | 'opened' | 'clicked' | 'bounced'
  const stateWeights: Array<[SendState, number]> = [
    ['sent',    20],
    ['opened',  15],
    ['clicked', 10],
    ['bounced',  5],
  ]

  // Simple weighted pick without importing rng to avoid circular dep issues
  function pickState(): SendState {
    const total = stateWeights.reduce((a, [, w]) => a + w, 0)
    let r = Math.random() * total
    for (const [v, w] of stateWeights) {
      r -= w
      if (r <= 0) return v
    }
    return 'sent'
  }

  const sends = Array.from({ length: 50 }, (_, i) => {
    const clientId    = ctx.clientIds[i % ctx.clientIds.length]!
    const sentAt      = new Date(now.getTime() - (i * 3600_000 + 86400_000)).toISOString()
    const state       = pickState()
    const openedAt    = state === 'opened' || state === 'clicked'
      ? new Date(new Date(sentAt).getTime() + 3600_000).toISOString()
      : null
    const clickedAt   = state === 'clicked'
      ? new Date(new Date(sentAt).getTime() + 7200_000).toISOString()
      : null
    const bouncedAt   = state === 'bounced'
      ? new Date(new Date(sentAt).getTime() + 1800_000).toISOString()
      : null

    return {
      id:                   detId('marketing_send', `${i}`),
      campaign_id:          campaignId,
      client_id:            clientId,
      studio_id:            ctx.studioId,
      channel:              'email' as const,
      recipient_email:      `client+${i}@demo.inkos.app`,
      provider_message_id:  `re_demo_${detId('msg', `${i}`).replace(/-/g, '')}`,
      sent_at:              sentAt,
      opened_at:            openedAt,
      clicked_at:           clickedAt,
      bounced_at:           bouncedAt,
    }
  })

  const { error: sendsErr } = await tolerantUpsert(sb, 'marketing_sends', sends, 'id')
  if (sendsErr) {
    log.module('marketing', 0, `marketing_sends (skipped: ${sendsErr.message})`)
  } else {
    log.module('marketing', sends.length, 'marketing_sends')
  }

  // ──────────────────────────────────────────────────────────────────────────
  // 7. email_suppression_list — 4 entries (mix of reasons)
  // ──────────────────────────────────────────────────────────────────────────
  const suppressions = [
    {
      id:        detId('suppression', 'bounce-1'),
      studio_id: ctx.studioId,
      email:     'bounce1@demo.inkos.app',
      reason:    'bounce' as const,
    },
    {
      id:        detId('suppression', 'bounce-2'),
      studio_id: ctx.studioId,
      email:     'bounce2@demo.inkos.app',
      reason:    'bounce' as const,
    },
    {
      id:        detId('suppression', 'complaint-1'),
      studio_id: ctx.studioId,
      email:     'complaint1@demo.inkos.app',
      reason:    'complaint' as const,
    },
    {
      id:        detId('suppression', 'manual-1'),
      studio_id: ctx.studioId,
      email:     'manual1@demo.inkos.app',
      reason:    'manual' as const,
    },
  ]
  const { error: suppErr } = await tolerantUpsert(sb, 'email_suppression_list', suppressions, 'id')
  if (suppErr) {
    log.module('marketing', 0, `email_suppression_list (skipped: ${suppErr.message})`)
  } else {
    log.module('marketing', suppressions.length, 'email_suppression_list')
  }

  // ──────────────────────────────────────────────────────────────────────────
  // 8. marketing_waitlist_rules — 1 rule for the demo studio
  // ──────────────────────────────────────────────────────────────────────────
  const waitlistRule = {
    studio_id:                    ctx.studioId,
    auto_promote_on_cancel:       true,
    auto_promote_window_minutes:  5,
    min_lead_time_hours:          24,
    notify_via:                   ['email'],
    template_subject:             'A slot just opened at {{studio_name}}',
    template_body:                'Hi {{client_first_name}}, a session slot just became available. Reply to this email or book online to claim it.',
  }
  const { error: wlErr } = await tolerantUpsert(
    sb, 'marketing_waitlist_rules', [waitlistRule], 'studio_id',
  )
  if (wlErr) {
    log.module('marketing', 0, `marketing_waitlist_rules (skipped: ${wlErr.message})`)
  } else {
    log.module('marketing', 1, 'marketing_waitlist_rules')
  }
}

