// ─── Event → update payload mapping ───────────────────────────────────────────

import type { Database } from '@/lib/supabase/types'

type MarketingSendUpdate = Database['public']['Tables']['marketing_sends']['Update']

function eventToUpdatePayload(eventType: ResendEvent['type']): MarketingSendUpdate | null {
  const ts = new Date().toISOString()
  switch (eventType) {
    case 'email.opened':    return { opened_at: ts }
    case 'email.clicked':   return { clicked_at: ts }
    case 'email.bounced':   return { bounced_at: ts }
    case 'email.complained': return { complained_at: ts }
    default: return null
  }
}

